import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        byte[] all = in.readAllBytes();
        int[] pos = {0};
        int n = (int) number(all, pos);
        long target = number(all, pos);
        long[] floors = new long[n];
        int[] fractions = new int[n];
        long base = 0;
        for (int i = 0; i < n; i++) {
            // Parse the price as integer part plus hundredths to avoid floating point.
            floors[i] = number(all, pos);
            int f = 0;
            if (pos[0] < all.length && all[pos[0]] == '.') {
                pos[0]++;
                for (int d = 0; d < 2; d++) {
                    f *= 10;
                    if (pos[0] < all.length && all[pos[0]] >= '0' && all[pos[0]] <= '9') f += all[pos[0]++] - '0';
                }
                while (pos[0] < all.length && all[pos[0]] > ' ') pos[0]++;
            }
            fractions[i] = f;
            base += floors[i];
        }
        long k = target - base;
        // Round up the k non-integer prices with the largest fractional parts (ties by index).
        long[] order = new long[n];
        int count = 0;
        for (int i = 0; i < n; i++)
            if (fractions[i] > 0) order[count++] = ((long) (100 - fractions[i]) << 20) | i;
        Arrays.sort(order, 0, count);
        for (int t = 0; t < k; t++) floors[(int) (order[t] & ((1 << 20) - 1))]++;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(floors[i]).append(i + 1 < n ? ' ' : '\n');
        System.out.print(sb);
    }

    static long number(byte[] s, int[] pos) {
        int p = pos[0];
        while (p < s.length && s[p] <= ' ') p++;
        boolean neg = p < s.length && s[p] == '-';
        if (neg) p++;
        long r = 0;
        while (p < s.length && s[p] >= '0' && s[p] <= '9') r = r * 10 + (s[p++] - '0');
        pos[0] = p;
        return neg ? -r : r;
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	target := nextInt()
	floors := make([]int64, n)
	fractions := make([]int64, n)
	base := int64(0)
	for i := 0; i < n; i++ {
		// Parse the price as integer part plus hundredths to avoid floating point.
		floors[i] = nextInt()
		f := int64(0)
		if pos < len(data) && data[pos] == '.' {
			pos++
			for d := 0; d < 2; d++ {
				f *= 10
				if pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
					f += int64(data[pos] - '0')
					pos++
				}
			}
			for pos < len(data) && data[pos] > ' ' {
				pos++
			}
		}
		fractions[i] = f
		base += floors[i]
	}
	k := target - base
	// Round up the k non-integer prices with the largest fractional parts (ties by index).
	order := make([]int64, 0, n)
	for i := 0; i < n; i++ {
		if fractions[i] > 0 {
			order = append(order, (100-fractions[i])<<20|int64(i))
		}
	}
	slices.Sort(order)
	for t := int64(0); t < k; t++ {
		floors[order[t]&(1<<20-1)]++
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i := 0; i < n; i++ {
		w.WriteString(strconv.FormatInt(floors[i], 10))
		if i+1 < n {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
